import{_ as a,o as t,c as i,a5 as s}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"12 — State Machines (sơ đồ trạng thái chi tiết)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/12-state-machines.md","filePath":"ba/12-state-machines.md"}'),e={name:"ba/12-state-machines.md"};function h(c,n,p,l,o,r){return t(),i("div",null,[...n[0]||(n[0]=[s(`<h1 id="_12-—-state-machines-so-đo-trang-thai-chi-tiet" tabindex="-1">12 — State Machines (sơ đồ trạng thái chi tiết) <a class="header-anchor" href="#_12-—-state-machines-so-đo-trang-thai-chi-tiet" aria-label="Permalink to &quot;12 — State Machines (sơ đồ trạng thái chi tiết)&quot;">​</a></h1><p>&gt; <strong>Ưu tiên BA 2026-10-18 cho Task:</strong> mục 4 hiện hành và <a href="./../feature/content-task-workflow/3-6-9-approval-sequence-creator-manager-client/spec.html">FR 3.6.9 v3</a> thay quy tắc QC/trạng thái trung gian của các ghi chú cũ. Một bản POST qua /editor, khóa nội dung khi review; reject/withdraw hợp lệ về IN_PROGRESS, gửi lại lượt mới; FINISHED không tự publish. Giai đoạn 1 là tài liệu, chưa có implementation Approval.</p><p>&gt; <strong>BA mới đã chốt 2026-10-15:</strong> Task chỉ còn TODO / IN_PROGRESS / IN_REVIEW / CANCELLED / FINISHED. Giao việc là metadata, không còn bước DETAIL_IDENTIFIED/ASSIGNED. Phải có mô tả + deadline hợp lệ trước giao; Creator được giao bấm bắt đầu mới IN_PROGRESS; sau đó Manager khóa sửa/giao lại. IN_REVIEW giữ QC → Manager → Client khi được cấu hình; reject về IN_PROGRESS, duyệt lại từ QC nếu có. Approval do thành viên khác triển khai. Autosave on-blur và action list chỉ assignment/deadline/start. Ghi chú mới này thay thế vòng đời Task lịch sử bên dưới; xem <a href="./../feature/content-task-workflow/task-five-state-inline-edit/spec.html">spec mới</a>.</p><p>&gt; <a href="./00-overview.html">&lt;&lt; Về Overview</a> &gt; Mục đích: mô tả chi tiết TỪNG cạnh chuyển trạng thái (transition) — điều kiện, ai được phép bấm — cho các entity có vòng đời phức tạp. Bổ sung cho mô tả bằng lời ở các file 04, 05, 07.</p><h2 id="_1-content-request" tabindex="-1">1. Content Request <a class="header-anchor" href="#_1-content-request" aria-label="Permalink to &quot;1. Content Request&quot;">​</a></h2><p>&gt; <strong>Quyết định mới nhất 2026-10-14 thay thế các ghi chú lịch sử về xử lý Request sau hoàn thành bên dưới:</strong> Task được chấp nhận gắn Campaign hiện tại và giữ Request nguồn; mọi Task chưa COMPLETED/CANCELLED và Request IN_PROGRESS chặn Manager hoàn thành Campaign. Sau hoàn thành thành công, PENDING tự hủy bằng durable queue; không tạo/sửa/tiếp nhận mới. Hủy Task là thao tác riêng có lựa chọn, lý do chung và xác nhận. Xem <a href="./../feature/media-package-campaign/campaign-closure/spec.html">Campaign closure</a>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        create (CLIENT)</span></span>
<span class="line"><span>              │</span></span>
<span class="line"><span>              ▼</span></span>
<span class="line"><span>         [PENDING] ──────update (CLIENT, chỉ khi PENDING)────────────┐</span></span>
<span class="line"><span>              │                                                        │</span></span>
<span class="line"><span>   set in_progress (MANAGER)                                          │</span></span>
<span class="line"><span>              │                                                        ▼</span></span>
<span class="line"><span>              ▼                                                  (vẫn PENDING)</span></span>
<span class="line"><span>      [IN_PROGRESS]</span></span>
<span class="line"><span>        │           │</span></span>
<span class="line"><span> accept(MANAGER)  deny(MANAGER)</span></span>
<span class="line"><span>        │           │</span></span>
<span class="line"><span>        ▼           ▼</span></span>
<span class="line"><span>   [ACCEPTED]    [DENIED]</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>  tự động sinh 1 Task mới (xem mục 3)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  PENDING ──cancel (CLIENT tạo Request)──► CANCELLED (terminal)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Từ</th><th>Đến</th><th>Ai bấm</th><th>Điều kiện</th></tr></thead><tbody><tr><td>(mới)</td><td>PENDING</td><td>CLIENT</td><td>Create Content Request</td></tr><tr><td>PENDING</td><td>PENDING (update nội dung)</td><td>CLIENT</td><td>Chỉ khi đang PENDING</td></tr><tr><td>PENDING</td><td>CANCELLED</td><td>CLIENT tạo Request</td><td>Hủy mềm; chỉ khi PENDING</td></tr><tr><td>PENDING</td><td>IN_PROGRESS</td><td>MANAGER thuộc Workspace</td><td>Bấm “Tiếp nhận yêu cầu”; xem trang không chuyển trạng thái; lưu người/thời điểm</td></tr><tr><td>IN_PROGRESS</td><td>ACCEPTED</td><td>MANAGER</td><td>→ tự sinh Task mới</td></tr><tr><td>IN_PROGRESS</td><td>DENIED</td><td>MANAGER</td><td>Kết thúc, không sinh Task</td></tr><tr><td>ACCEPTED/DENIED/CANCELLED</td><td>*</td><td>KHÔNG AI</td><td>Trạng thái cuối, không mở lại</td></tr></tbody></table><p>Xác nhận người dùng 2026-10-13: IN_PROGRESS hiển thị “Đang xem xét”, không phải Task đang thực hiện. Client chỉ sửa title/description/type/dueDate và hủy trong PENDING. Chỉ tạo mới khi Campaign IN_PROGRESS, deployment SUCCEEDED; không tạo khi COMPLETED. Request đã có tiếp tục xử lý sau hoàn thành, không tự hủy. Các thay đổi BA chung cần lead/team review theo team guide.</p><h2 id="_2-media-package-đam-phan" tabindex="-1">2. Media Package (đàm phán) <a class="header-anchor" href="#_2-media-package-đam-phan" aria-label="Permalink to &quot;2. Media Package (đàm phán)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  Manager chọn template</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>    [DRAFT] ──(Client request thay đổi)──► [CLIENT_REQUESTED_CHANGE]</span></span>
<span class="line"><span>        │                                          │</span></span>
<span class="line"><span>        │                          (Agency counter-offer)</span></span>
<span class="line"><span>        │                                          │</span></span>
<span class="line"><span>        │                                          ▼</span></span>
<span class="line"><span>        │                                [AGENCY_COUNTERED] ──(lặp lại negotiate)──┐</span></span>
<span class="line"><span>        │                                          │                                │</span></span>
<span class="line"><span>        │                                          ▼                                │</span></span>
<span class="line"><span>        └──────────────────► cả 2 bên đồng ý ──► [APPROVED] ◄───────────────────────┘</span></span></code></pre></div><ul><li>Vòng lặp <code>CLIENT_REQUESTED_CHANGE ↔ AGENCY_COUNTERED</code> có thể xảy ra nhiều lần (FR 3.5.3: &quot;Quá trình đó được diễn ra cho đến khi cả 2 bên chốt được gói cuối cùng&quot;).</li><li><code>APPROVED</code> yêu cầu <strong>cả 2 phía xác nhận</strong> (approvedByAgencyAt VÀ approvedByClientAt đều có giá trị) — không phải 1 bên approve là xong.</li><li>Sau khi <code>APPROVED</code> → có thể tạo Media Campaign (mục tiếp).</li></ul><h2 id="_3-media-campaign" tabindex="-1">3. Media Campaign <a class="header-anchor" href="#_3-media-campaign" aria-label="Permalink to &quot;3. Media Campaign&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Package APPROVED</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>   [DRAFT] ──(Agency tạo nội dung chi tiết)</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>cả 2 bên approve</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>  [APPROVED] ──(nhấn triển khai)──► sinh Task backlog (N task) ──► [IN_PROGRESS]</span></span>
<span class="line"><span>                                                                          │</span></span>
<span class="line"><span>                                                            Manager mark completed</span></span>
<span class="line"><span>                                                                          │</span></span>
<span class="line"><span>                                                                          ▼</span></span>
<span class="line"><span>                                                                   [COMPLETED]</span></span></code></pre></div><ul><li>Giống Package, <code>APPROVED</code> yêu cầu đồng thuận 2 phía.</li><li><strong>[Cập nhật BA 2026-10-08]</strong> <code>IN_PROGRESS</code> sau deploy thành công; Manager chủ động mark <code>COMPLETED</code> từ <code>IN_PROGRESS</code>. Được phép khi còn Task chưa hoàn thành nhưng bắt buộc ghi lý do; không đổi trạng thái hoặc tự khóa workflow các Task con.</li><li>Một Workspace chỉ có một Campaign; chiến dịch mới dùng Workspace mới. Owner được chọn từng thành viên và tùy chọn timezone khi nhân bản Workspace (DA-1255); tài nguyên chờ module riêng. Đề xuất nhiều đợt trong cùng Workspace không còn áp dụng.</li></ul><p>&gt; <strong>Campaign Addendum bên dưới là BA lịch sử cần review:</strong> chưa có task riêng và &gt; không được tạo Campaign thứ hai trong cùng Workspace để lách quan hệ 1:1 mới.</p><p><strong>[CONFIRMED 2026-09-17] Campaign Addendum — bổ sung cho tính immutable:</strong> Campaign gốc sau <code>APPROVED</code> vẫn immutable (không sửa trực tiếp), nhưng khi phát sinh khối lượng công việc lớn giữa chiến dịch (không phải 1 task lẻ qua Content Request hay Manager add thủ công), Agency tạo 1 <strong>Campaign Addendum</strong> — bản bổ sung link tới Campaign gốc (<code>parentCampaignId</code>), có thể chứa nhiều Task mới, cũng phải qua chu trình duyệt 2 phía riêng (Draft → Approved) như Campaign gốc. Mục đích: Task lớn phát sinh giữa kỳ vẫn truy vết được về đúng Campaign nào sinh ra nó, phục vụ báo cáo/billing — không để lẫn vào Task rời không rõ nguồn gốc như Manual Task đơn lẻ. Xem entity đề xuất tại <a href="./11-data-entities-glossary.html">11-data-entities-glossary.md</a>.</p><h2 id="_4-task-—-approval-sequence-hien-hanh-2026-10-18" tabindex="-1">4. Task — Approval Sequence (hiện hành 2026-10-18) <a class="header-anchor" href="#_4-task-—-approval-sequence-hien-hanh-2026-10-18" aria-label="Permalink to &quot;4. Task — Approval Sequence (hiện hành 2026-10-18)&quot;">​</a></h2><p>Nguồn: <a href="./../feature/content-task-workflow/3-6-9-approval-sequence-creator-manager-client/spec.html">spec FR3.6.9 v3</a>. Thay toàn bộ sơ đồ QC/ASSIGNED/skip-approval cũ cho luồng mới; không tự chuyển đổi/xóa dữ liệu legacy.</p><table tabindex="0"><thead><tr><th>Trước</th><th>Action hợp lệ</th><th>Sau</th></tr></thead><tbody><tr><td>TODO</td><td>Assignee Creator bắt đầu; description + dueDate hợp lệ</td><td>IN_PROGRESS, ghi firstStartedAt/By</td></tr><tr><td>IN_PROGRESS</td><td>Assignee lưu bài POST hợp lệ và submit</td><td>IN_REVIEW / MANAGER</td></tr><tr><td>IN_REVIEW / MANAGER</td><td>Manager approve, không cần Client</td><td>FINISHED</td></tr><tr><td>IN_REVIEW / MANAGER</td><td>Manager approve, cần Client</td><td>IN_REVIEW / CLIENT</td></tr><tr><td>IN_REVIEW / CLIENT</td><td>Một Client active bất kỳ approve</td><td>FINISHED</td></tr><tr><td>IN_REVIEW / MANAGER hoặc CLIENT</td><td>Đúng người duyệt reject có lý do</td><td>IN_PROGRESS</td></tr><tr><td>IN_REVIEW / MANAGER, chưa decision</td><td>Assignee Creator withdraw</td><td>IN_PROGRESS</td></tr><tr><td>Task chưa kết thúc</td><td>Flow cancel được cấp quyền hiện có</td><td>CANCELLED</td></tr></tbody></table><ul><li>Không có QC; chỉ năm trạng thái. reviewStep chỉ có MANAGER/CLIENT lúc IN_REVIEW, null ngoài review.</li><li>Lượt đầu 1, mỗi submit lại thành công sau reject/withdraw tăng lượt; decision cũ append-only nhưng không hiệu lực cho lượt mới. Chỉ APPROVE/REJECT tạo decision, tối đa hai/lượt.</li><li>Withdraw không được sau Manager decision; race với decision chỉ một bên thắng. Client đầu tiên quyết định hợp lệ kết thúc bước Client; người khác dùng màn hình cũ bị conflict.</li><li>Thiếu Client active khi được yêu cầu thì chặn submit, báo Manager bổ sung. Hết Client khi đã chờ thì giữ bước/Manager approval, không tự skip. Thay Manager thì Manager active hiện tại được duyệt.</li><li>POST dùng /editor và một Post hiện tại; khóa sửa khi review, reject/withdraw hợp lệ mới sửa lại. Chưa quản lý snapshot/khôi phục nội dung lượt trước; lịch sử là decision, không phải bản nội dung.</li><li>First-start evidence giữ nguyên qua reject/withdraw; Manager vẫn khóa sửa brief/deadline/giao lại. Task FINISHED/CANCELLED không reopen; bình luận vẫn theo FR3.6.3.</li><li>Cancel phải xóa bước chờ/đóng metadata, không xóa decision. Không duyệt sau hủy/hoàn thành Campaign; giữ điều kiện Campaign closure hiện có.</li><li>FINISHED không tự enqueue Publish. Xuất bản là action/module riêng; Admin moderation không thay decision Task.</li><li>Đây là contract đích của giai đoạn 1, chưa phải implementation đã chạy. Legacy QC/thiếu reviewStep/round chỉ đọc và inventory riêng, không tự backfill.</li></ul><h2 id="_5-task-loai-livestream-—-trang-thai-rieng" tabindex="-1">5. Task loại Livestream — trạng thái riêng <a class="header-anchor" href="#_5-task-loai-livestream-—-trang-thai-rieng" aria-label="Permalink to &quot;5. Task loại Livestream — trạng thái riêng&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[PRE_LIVE] ──(bắt đầu buổi live)──► [LIVE] ──(kết thúc buổi live)──► [POST_LIVE] ──► [DONE]</span></span>
<span class="line"><span>    │                                  │</span></span>
<span class="line"><span>    └──────────(hủy buổi live)─────────┴──────────────────────────────────────► [CANCEL]</span></span></code></pre></div><ul><li><code>PRE_LIVE</code>: chuẩn bị (idea, script, setup, quay chuẩn bị — xem checklist ở <a href="./05-content-task-workflow.html">05-content-task-workflow.md</a> mục 3).</li><li><code>LIVE</code>: đang phát trực tiếp.</li><li><code>POST_LIVE</code>: xử lý sau live (retouch, cắt clip highlight để chạy hook).</li><li><code>DONE</code>/<code>CANCEL</code>: 2 trạng thái kết thúc — Cancel có thể xảy ra ở bất kỳ giai đoạn PRE_LIVE hoặc LIVE.</li><li>State này lồng bên trong Task chính (Task cha vẫn đi qua Approval Sequence ở mục 4 sau khi Livestream state đạt DONE).</li></ul><h2 id="_6-third-party-collaborator-—-trang-thai-hop-tac" tabindex="-1">6. Third-party Collaborator — trạng thái hợp tác <a class="header-anchor" href="#_6-third-party-collaborator-—-trang-thai-hop-tac" aria-label="Permalink to &quot;6. Third-party Collaborator — trạng thái hợp tác&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[CONTACTED] ──► [NEGOTIATING] ──► [CONFIRMED] ──► [LIVE_ON_AIR]</span></span></code></pre></div><ul><li>Cập nhật hoàn toàn thủ công bởi Manager/Creator — không có transition tự động, không có API bên thứ 3 kích hoạt chuyển trạng thái (khác hẳn Task/Post publish tự động qua API).</li><li>Có thể revert lùi trạng thái (ví dụ từ NEGOTIATING quay lại CONTACTED nếu đàm phán đổ vỡ) — không phải chuỗi 1 chiều cứng nhắc như Task Approval Sequence.</li></ul><h2 id="_7-post-—-trang-thai-publish-sau-khi-task-hoan-thanh" tabindex="-1">7. Post — trạng thái Publish (sau khi Task hoàn thành) <a class="header-anchor" href="#_7-post-—-trang-thai-publish-sau-khi-task-hoan-thanh" aria-label="Permalink to &quot;7. Post — trạng thái Publish (sau khi Task hoàn thành)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[FINISHED Task] --thao tác xuất bản riêng--&gt; [PENDING publish] ──► [IN_PROGRESS] ──► [DONE] hoặc [FAIL]</span></span></code></pre></div><ul><li>Tương ứng FR 3.8.8 View Status Tracking: &quot;Pending, In Progress, Done, Fail&quot;.</li><li>BA 2026-10-18: cạnh xuất bản trên là thao tác riêng của module publishing, không phải side-effect tự động của Task approval. Không đổi queue/callback hoặc cơ chế retry của module đó.</li><li><strong>[CONFIRMED 2026-09-17]</strong> <code>FAIL</code> <strong>có retry tự động, theo config</strong> — số lần retry và backoff không hardcode, đọc từ setting (kế thừa tiền lệ retry 3 lần exponential backoff ở hệ thống cũ làm giá trị mặc định, nhưng phải config được để chỉnh khi cần mà không cần deploy lại code publisher-service).</li></ul>`,30)])])}const u=a(e,[["render",h]]);export{g as __pageData,u as default};
